akq(a){return""+a+" \u05d1\u05e7\u05e9\u05d5\u05ea \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \xb7 \u05e0\u05e2\u05d3\u05db\u05df \u05db\u05e9\u05ea\u05ea\u05e4\u05e0\u05d4"},
gakr(){return"\u05d4\u05ea\u05e4\u05e0\u05d4 \u05dc\u05da \u05ea\u05d5\u05e8! \xb7 \u05dc\u05e6\u05e4\u05d9\u05d9\u05d4 \u05d1\u05d4\u05e6\u05e2\u05d4"},
gak8(){return"\u05e0\u05e2\u05d3\u05db\u05df \u05d0\u05d5\u05ea\u05da \u05db\u05e9\u05d4\u05e9\u05e2\u05d4 \u05e9\u05d1\u05d9\u05e7\u05e9\u05ea \u05de\u05ea\u05e4\u05e0\u05d4. \u05d0\u05dc\u05d4 \u05dc\u05d0 \u05ea\u05d5\u05e8\u05d9\u05dd \u2014 \u05d5\u05dc\u05db\u05df \u05d4\u05df \u05de\u05d5\u05e4\u05d9\u05e2\u05d5\u05ea \u05db\u05d0\u05df, \u05d1\u05e0\u05e4\u05e8\u05d3 \u05de\u05d1\u05e7\u05e9\u05d5\u05ea \u05e9\u05de\u05de\u05ea\u05d9\u05e0\u05d5\u05ea \u05dc\u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e2\u05e1\u05e7."},
gakt(){return"\u05d1\u05e7\u05e9\u05d5\u05ea \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea"},
