gakG(){return"\u05e4\u05d2 \u05ea\u05d5\u05e7\u05e3 \u05d4\u05d1\u05e7\u05e9\u05d4"},
gakE(){return"\u05d9\u05e9 \u05dc\u05da \u05ea\u05d5\u05e8 \u05d1\u05e9\u05e2\u05d4 \u05d4\u05d6\u05d5"},
gake(){return"\u05d2\u05dd \u05e2\u05dc \u05e9\u05e2\u05d5\u05ea \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u2014 \u05e2\u05d3 \u05e9\u05e2\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9"},
akh(a){return"\u05d4\u05e9\u05e2\u05d4 \u05d4\u05ea\u05e4\u05e0\u05ea\u05d4 \u2014 \u05e9\u05de\u05d5\u05e8\u05d4 \u05dc\u05da \u05e2\u05d3 "+a},
YJ(a){return"\u05e0\u05d5\u05ea\u05e8\u05d5 "+a},
gYF(){return"\u05dc\u05e6\u05e4\u05d9\u05d9\u05d4 \u05d1\u05ea\u05d5\u05e8"},
