gN3(){return"\u05d1\u05d7\u05d9\u05e8\u05ea \u05e9\u05e2\u05d4 \u05d0\u05d7\u05e8\u05ea"},
akB(a){return"\u05d4\u05e9\u05e2\u05d4 "+a+" \u05ea\u05e4\u05d5\u05e1\u05d4 \u05db\u05e8\u05d2\u05e2"},
gakA(){return"\u05e8\u05d5\u05e6\u05d4 \u05e9\u05e0\u05e2\u05d3\u05db\u05df \u05d0\u05d5\u05ea\u05da \u05d0\u05dd \u05d4\u05d9\u05d0 \u05ea\u05ea\u05e4\u05e0\u05d4?"},
